INSERT INTO `appraisal_question` (`questionid`, `question`, `sectionid`) VALUES
(1, 'What were the main responsibilities?', 1),
(2, 'What responsibilities took up the largest proportion of working hours?', 1),
(3, 'What went well, what could have gone better ?', 1),
(4, 'What were the major difficulties that arose ?', 1),
(5, 'What could have gone better under what circumstances?', 1),
(6, 'Which qualifications need to be given special attention in future?', 1),
(7, 'Were the agreed goals achieved? To what degree  ', 2),
(8, 'What can the shortfalls in goal achievement be attributed to  ', 2),
(9, 'What can be learned for the future from analysing the discrepancies in terms of goal achievement?', 2),
(10, 'How did you fulfil your responsibilities - what were you satisfied with or unsatisfied with?  ', 3),
(11, 'What are your strengths in the present function?', 3),
(12, 'What are your weaknesses?', 3),
(13, 'What provisions can be made to ensure that these weaknesses do not become a major issue? ', 3),
(14, 'Where do you see potential in terms of your professional development?', 4),
(15, 'Do you expect professional development? If yes, what kind?', 4),
(16, 'What responsibilities would you like to assume?', 4),
(17, 'How satisfied are you with your current function? ', 4);
INSERT INTO `appraisal_section` (`sectionid`, `sectiontext`, `description`, `scale`) VALUES
