(3, 'Employees’ main capabilities, analysis of strengths and weaknesses', '<ul>\r\n       <li> 6 - Completely true description </li> \r\n       <li> 5 - Largely true </li> \r\n       <li> 4 - Somewhat true </li> \r\n       <li> 3 - Somewhat false </li> \r\n       <li> 2 - Largely false </li> \r\n       <li> 1 - Completely false description </li> \r\n        </ul>', 6),
(4, 'Development and Career Preferences', '<ul>\r\n       <li> 6 - Completely true description </li> \r\n       <li> 5 - Largely true </li> \r\n       <li> 4 - Somewhat true </li> \r\n       <li> 3 - Somewhat false </li> \r\n       <li> 2 - Largely false </li> \r\n       <li> 1 - Completely false description </li> \r\n        </ul>', 6);
